:where([data-moru-registry]) .ui-marker {
  min-width: 0;
  max-width: 100%;
  color: var(--ui-text);
  font-family: var(--ui-font-family);
  font-size: var(--ui-type-body-size);
  font-weight: var(--ui-type-body-weight);
  line-height: var(--ui-type-body-line-height);
  letter-spacing: var(--ui-type-body-letter-spacing);
}
:where([data-moru-registry]) .ui-marker {
  font-size: var(--ui-type-caption-size);
  font-weight: var(--ui-type-caption-weight);
  line-height: var(--ui-type-caption-line-height);
  letter-spacing: var(--ui-type-caption-letter-spacing);
  color: var(--ui-muted);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-marker {
  display: flex;
  align-items: center;
  gap: var(--ui-control-gap);
  padding-block: calc(var(--ui-space) * 2);
}
:where([data-moru-registry]) .ui-marker-icon {
  display: flex;
  flex-shrink: 0;
  align-items: center;
}
:where([data-moru-registry]) .ui-marker-icon > svg {
  width: var(--ui-icon-size-md);
  height: var(--ui-icon-size-md);
}
:where([data-moru-registry]) .ui-marker-content {
  min-width: 0;
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-marker[data-variant='border'] {
  border-bottom: var(--ui-border-width) solid var(--ui-border);
}
:where([data-moru-registry]) .ui-marker[data-variant='separator'] {
  justify-content: center;
  text-align: center;
}
:where([data-moru-registry]) .ui-marker[data-variant='separator']::before,
:where([data-moru-registry]) .ui-marker[data-variant='separator']::after {
  content: '';
  height: var(--ui-border-width);
  background: var(--ui-border);
  flex: 1;
  min-width: 8px;
}
:where([data-moru-registry]) .ui-marker[data-tone='success'] {
  color: var(--ui-success-surface-text);
}
:where([data-moru-registry]) .ui-marker[data-tone='warning'] {
  color: var(--ui-warning-surface-text);
}
:where([data-moru-registry]) .ui-marker[data-tone='danger'] {
  color: var(--ui-danger-surface-text);
}
:where([data-moru-registry]) .ui-marker[data-tone='info'] {
  color: var(--ui-info-surface-text);
}

